// advance 子命令：状态机流转的唯一命令行入口。
// 用法：advance project <目标状态>（项目全局只有一个，不用编号）
//      advance <milestone|sprint|tick> <编号> <目标状态>
async function cmdAdvance({ root, positionals, flags }) {
  const kind = positionals[0];
  if (!kind) {
    throw new CliError('advance 需要指明对象种类：advance project <目标状态>，或 advance milestone|sprint|tick <编号> <目标状态>');
  }
  let id = null;
  let toState;
  if (kind === 'project') {
    toState = positionals[1];
    if (!toState) {
      throw new CliError('advance project 需要目标状态，例如：advance project phase2');
    }
  } else {
    id = positionals[1];
    toState = positionals[2];
    if (!id || !toState) {
      throw new CliError(`advance ${kind} 需要「编号 + 目标状态」两个参数，例如：advance ${kind} X1 done`);
    }
  }
  const actor = typeof flags.actor === 'string' && flags.actor.trim() !== '' ? flags.actor : '未署名';
  try {
    const result = await advance(root, kind, id, toState, { actor });
    return { output: { ok: true, ...result }, exit: EXIT.OK };
  } catch (err) {
    // 非法流转要有专属退出码，带外调度器靠它区分「走错路」和一般性出错
    if (err instanceof IllegalTransition) {
      throw new CliError(err.message, EXIT.ILLEGAL_TRANSITION);
    }
    throw err;
  }
}

